const agora = new Date();

// Horário configurável da Som Renovo
// Segunda a sexta: 08:00 às 18:00
// Sábado: 08:00 às 13:00
// Domingo: fechado

const dia = agora.getDay();
const hora = agora.getHours();
const minuto = agora.getMinutes();
const minutosAtual = hora * 60 + minuto;

let inicio = null;
let fim = null;

if (dia >= 1 && dia <= 5) {
  inicio = 8 * 60;
  fim = 18 * 60;
} else if (dia === 6) {
  inicio = 8 * 60;
  fim = 13 * 60;
}

const dentroDoHorario = inicio !== null && minutosAtual >= inicio && minutosAtual < fim;

return [{
  json: {
    ...$json,
    dentroDoHorario,
    atendimentoIA: !dentroDoHorario
  }
}];

const texto = $input.first().json.output || '';

const mensagens = texto
  .split(/\\/)
  .map(item => item.trim())
  .filter(item => item.length > 0);

return mensagens.map(item => ({
  json: {
    item,
    telefone: $('Coleta').first().json.telefone
  }
}));

