CREATE TABLE IF NOT EXISTS public.som_renovo_messages (
    id BIGSERIAL PRIMARY KEY,
    telefone VARCHAR(255) NOT NULL,
    nome VARCHAR(255),
    tipo VARCHAR(100),
    mensagem TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_som_renovo_messages_telefone
ON public.som_renovo_messages(telefone);

CREATE INDEX IF NOT EXISTS idx_som_renovo_messages_created_at
ON public.som_renovo_messages(created_at);
